const addDays=(date,days)=>{if(!date)return"";const d=new Date(`${date}T12:00:00`);d.setDate(d.getDate()+Number(days||0));return d.toISOString().slice(0,10)};
const addMonths=(date,months)=>{if(!date)return"";const d=new Date(`${date}T12:00:00`);d.setMonth(d.getMonth()+Number(months||0));return d.toISOString().slice(0,10)};
const daysLeft=d=>d?Math.ceil((new Date(`${d}T23:59:59`)-new Date())/86400000):null;
