 return <div className="profile-switcher" ref={ref}><button className={`user-chip user-chip-button ${open?"open":""}`} onClick={()=>setOpen(v=>!v)} aria-haspopup="menu" aria-expanded={open}><span className="avatar">{(auth.user.name||"U").slice(0,2).toUpperCase()}</span><div><strong>{auth.user.name}</strong><small>{auth.adminMode?`Espace · ${auth.adminMode.name}`:"Administrateur"}</small></div><ChevronDown className="profile-chevron" size={15}/></button>{open&&<div className="profile-menu" role="menu"><div className="profile-menu-head"><strong>Changer d’espace</strong><small>Vous restez connecté en tant qu’administrateur.</small></div><div className="profile-search"><Search size={15}/><input value={search} onChange={e=>setSearch(e.target.value)} placeholder="Rechercher un délégué…" autoFocus/></div><div className="profile-account-list"><button className={`profile-account ${!auth.adminMode?"selected":""}`} onClick={chooseAdmin}><span className="profile-account-avatar admin">{(auth.user.name||"A").slice(0,2).toUpperCase()}</span><span><strong>Administration</strong><small>Pilotage global</small></span>{!auth.adminMode&&<CheckCircle2 size={17}/>}</button>{accounts.map(m=><button key={m.id} className={`profile-account ${auth.adminMode?.id===m.id?"selected":""}`} onClick={()=>chooseDelegate(m.id)}><span className="profile-account-avatar">{(m.name||"D").slice(0,2).toUpperCase()}</span><span><strong>{m.name}</strong><small>{m.email||m.sector||"Délégué"}</small></span>{auth.adminMode?.id===m.id&&<CheckCircle2 size={17}/>}</button>)}{!accounts.length&&<div className="profile-empty">Aucun compte correspondant.</div>}</div></div>}</div>
